-- Rehberlik R3 — ölçme araçları (owner, 12 Nov 2026).
-- New item types (A/B, evet/hayır, çoktan seçmeli, kısa yanıt, arkadaş seçimi), counsellor drafts that the Super Admin
-- approves, and anonymous school surveys (RİBA, okul iklimi). Every new instrument below is written by ANUNEX as an
-- educational, non-diagnostic tool and starts INACTIVE in REVIEW: nothing reaches a student before an expert approves it
-- in the Super Admin screen. RİBA forms carry no items until their use is confirmed from the official MEB source.
ALTER TABLE guidance_assessment_instruments ADD COLUMN institution_id TEXT REFERENCES institutions(id) ON DELETE CASCADE;
ALTER TABLE guidance_assessment_instruments ADD COLUMN owner_user_id TEXT REFERENCES users(id);
ALTER TABLE guidance_assessment_instruments ADD COLUMN review_status TEXT NOT NULL DEFAULT 'APPROVED' CHECK(review_status IN ('DRAFT','REVIEW','APPROVED','REJECTED'));
ALTER TABLE guidance_assessment_instruments ADD COLUMN review_note TEXT;
ALTER TABLE guidance_assessment_instruments ADD COLUMN grade_min INTEGER;
ALTER TABLE guidance_assessment_instruments ADD COLUMN grade_max INTEGER;

CREATE TABLE IF NOT EXISTS guidance_survey_templates (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  kind TEXT NOT NULL CHECK(kind IN ('RIBA','CLIMATE')),
  title TEXT NOT NULL,
  description TEXT,
  forms_json TEXT NOT NULL,
  review_status TEXT NOT NULL DEFAULT 'REVIEW' CHECK(review_status IN ('REVIEW','APPROVED','REJECTED')),
  review_note TEXT,
  active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS guidance_surveys (
  id TEXT PRIMARY KEY,
  institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE,
  template_id TEXT NOT NULL REFERENCES guidance_survey_templates(id),
  title TEXT NOT NULL,
  forms_json TEXT NOT NULL,            -- the forms as they were when the survey opened
  sample_pct INTEGER NOT NULL DEFAULT 30 CHECK(sample_pct BETWEEN 5 AND 100),
  status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')),
  created_by TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  closed_at TEXT
);
-- who was asked (to show the survey and stop a second answer) — never linked to an answer
CREATE TABLE IF NOT EXISTS guidance_survey_invites (
  id TEXT PRIMARY KEY,
  survey_id TEXT NOT NULL REFERENCES guidance_surveys(id) ON DELETE CASCADE,
  form_code TEXT NOT NULL,
  class_id TEXT REFERENCES classes(id) ON DELETE SET NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  responded INTEGER NOT NULL DEFAULT 0 CHECK(responded IN (0,1)),
  UNIQUE(survey_id, user_id, form_code)
);
-- the answers: form and class only, no person
CREATE TABLE IF NOT EXISTS guidance_survey_responses (
  id TEXT PRIMARY KEY,
  survey_id TEXT NOT NULL REFERENCES guidance_surveys(id) ON DELETE CASCADE,
  form_code TEXT NOT NULL,
  class_id TEXT REFERENCES classes(id) ON DELETE SET NULL,
  answers_json TEXT NOT NULL,
  created_on TEXT NOT NULL DEFAULT (date('now'))
);
CREATE INDEX IF NOT EXISTS idx_guidance_survey_responses ON guidance_survey_responses(survey_id, form_code);

INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_rba_v2_a','RBA_EDU_V2_A','RBA Öğrenme ve Çalışma Profili · 4–6. sınıf','RBA','2.0','Planlama, düzenli çalışma, hata inceleme, sebat, zaman yönetimi ve odak davranışlarını eğitim amacıyla değerlendirir. ANUNEX’teki ölçülen verilerle ve rehber öğretmen yorumuyla birlikte okunur. Tanı değildir; öğrenciyi etiketlemez.','{"scale": {"min": 1, "max": 5, "labels": ["Hiç", "Nadiren", "Bazen", "Çoğu zaman", "Her zaman"]}, "items": [{"id": "pla1", "dimension": "plan_adherence", "text": "Ödevlerimi ve çalışacaklarımı önceden bir yere yazarım."}, {"id": "pla2", "dimension": "plan_adherence", "text": "Yapacağım işleri sıraya koyarım."}, {"id": "pla3", "dimension": "plan_adherence", "text": "Plan yaptığımda ona uymaya çalışırım."}, {"id": "pla4", "dimension": "plan_adherence", "text": "Ders çalışmaya başlamadan ne yapacağımı bilirim."}, {"id": "con1", "dimension": "consistency", "text": "Her gün biraz ders çalışırım."}, {"id": "con2", "dimension": "consistency", "text": "Ders çalışmayı sınavdan önceki güne bırakmam."}, {"id": "con3", "dimension": "consistency", "text": "Ders çalışma saatim genelde bellidir."}, {"id": "con4", "dimension": "consistency", "text": "Tatil günlerinde de biraz tekrar yaparım."}, {"id": "err1", "dimension": "error_review", "text": "Yanlış yaptığım soruya tekrar bakarım."}, {"id": "err2", "dimension": "error_review", "text": "Neden yanlış yaptığımı anlamaya çalışırım."}, {"id": "err3", "dimension": "error_review", "text": "Yanlış yaptığım konuyu yeniden çalışırım."}, {"id": "err4", "dimension": "error_review", "text": "Yanlışlarımı bir yere not ederim."}, {"id": "per1", "dimension": "persistence", "text": "Zor bir soruda hemen pes etmem."}, {"id": "per2", "dimension": "persistence", "text": "Anlamadığım bir şeyi öğretmenime sorarım."}, {"id": "per3", "dimension": "persistence", "text": "Bir işe başlayınca bitirmeye çalışırım."}, {"id": "per4", "dimension": "persistence", "text": "Kötü bir not alınca daha çok çalışırım."}, {"id": "pac1", "dimension": "pace", "text": "Ödevlerimi zamanında bitiririm."}, {"id": "pac2", "dimension": "pace", "text": "Soruları çözerken acele etmem."}, {"id": "pac3", "dimension": "pace", "text": "Zor soruda çok takılmadan devam ederim."}, {"id": "pac4", "dimension": "pace", "text": "Ders çalışırken ara vermeyi unutmam."}, {"id": "foc1", "dimension": "focus", "text": "Ders çalışırken başka şeylerle uğraşmam."}, {"id": "foc2", "dimension": "focus", "text": "Çalıştığım yer sessiz ve düzenlidir."}, {"id": "foc3", "dimension": "focus", "text": "Derste öğretmenimi dikkatle dinlerim."}, {"id": "foc4", "dimension": "focus", "text": "Okuduğum şeyi anlamadan geçmem."}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',4,6,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_rba_v2_b','RBA_EDU_V2_B','RBA Öğrenme ve Çalışma Profili · 7–8. sınıf','RBA','2.0','Planlama, düzenli çalışma, hata inceleme, sebat, zaman yönetimi ve odak davranışlarını eğitim amacıyla değerlendirir. ANUNEX’teki ölçülen verilerle ve rehber öğretmen yorumuyla birlikte okunur. Tanı değildir; öğrenciyi etiketlemez.','{"scale": {"min": 1, "max": 5, "labels": ["Hiç", "Nadiren", "Bazen", "Çoğu zaman", "Her zaman"]}, "items": [{"id": "pla1", "dimension": "plan_adherence", "text": "Haftalık çalışmamı önceden planlarım."}, {"id": "pla2", "dimension": "plan_adherence", "text": "Planladığım çalışmaları çoğu gün yaparım."}, {"id": "pla3", "dimension": "plan_adherence", "text": "Planım aksarsa ertesi gün telafi ederim."}, {"id": "pla4", "dimension": "plan_adherence", "text": "Çalışmaya başlamadan o gün neyi bitireceğimi belirlerim."}, {"id": "con1", "dimension": "consistency", "text": "Haftanın çoğu günü ders çalışırım."}, {"id": "con2", "dimension": "consistency", "text": "Konuları sınavdan hemen önce değil, zamanla çalışırım."}, {"id": "con3", "dimension": "consistency", "text": "Belli saatlerde ders çalışma alışkanlığım var."}, {"id": "con4", "dimension": "consistency", "text": "Hafta sonu kısa da olsa tekrar yaparım."}, {"id": "err1", "dimension": "error_review", "text": "Yanlış yaptığım soruların çözümünü incelerim."}, {"id": "err2", "dimension": "error_review", "text": "Yanlışımın nedenini bulmaya çalışırım (dikkat, bilgi, süre…)."}, {"id": "err3", "dimension": "error_review", "text": "Yanlış yaptığım konulardan yeni sorular çözerim."}, {"id": "err4", "dimension": "error_review", "text": "Yanlışlarımı bir deftere ya da listeye yazarım."}, {"id": "per1", "dimension": "persistence", "text": "Zor bir soruyla karşılaşınca farklı yollar denerim."}, {"id": "per2", "dimension": "persistence", "text": "Anlamadığım konuyu öğretmenime ya da arkadaşıma sorarım."}, {"id": "per3", "dimension": "persistence", "text": "Başladığım ödevi yarım bırakmam."}, {"id": "per4", "dimension": "persistence", "text": "Düşük bir sonuçtan sonra çalışmayı bırakmam."}, {"id": "pac1", "dimension": "pace", "text": "Ödevlerimi teslim gününden önce bitiririm."}, {"id": "pac2", "dimension": "pace", "text": "Soruları çözerken süremi kontrol ederim."}, {"id": "pac3", "dimension": "pace", "text": "Uzun süren bir soruyu sonraya bırakabilirim."}, {"id": "pac4", "dimension": "pace", "text": "Çalışırken kısa molalar veririm."}, {"id": "foc1", "dimension": "focus", "text": "Ders çalışırken telefonu ya da tableti uzak tutarım."}, {"id": "foc2", "dimension": "focus", "text": "Çalışma ortamımı düzenli tutarım."}, {"id": "foc3", "dimension": "focus", "text": "Derste anlatılanı dikkatle takip ederim."}, {"id": "foc4", "dimension": "focus", "text": "Okuduğum metni anlamadan bir sonrakine geçmem."}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',7,8,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_rba_v2_c','RBA_EDU_V2_C','RBA Öğrenme ve Çalışma Profili · 9–12. sınıf','RBA','2.0','Planlama, düzenli çalışma, hata inceleme, sebat, zaman yönetimi ve odak davranışlarını eğitim amacıyla değerlendirir. ANUNEX’teki ölçülen verilerle ve rehber öğretmen yorumuyla birlikte okunur. Tanı değildir; öğrenciyi etiketlemez.','{"scale": {"min": 1, "max": 5, "labels": ["Hiç", "Nadiren", "Bazen", "Çoğu zaman", "Her zaman"]}, "items": [{"id": "pla1", "dimension": "plan_adherence", "text": "Çalışma planımı hedeflerime ve sınav takvimime göre hazırlarım."}, {"id": "pla2", "dimension": "plan_adherence", "text": "Planladığım çalışmaların büyük kısmını zamanında tamamlarım."}, {"id": "pla3", "dimension": "plan_adherence", "text": "Planım aksadığında planı gerçekçi biçimde yeniden düzenlerim."}, {"id": "pla4", "dimension": "plan_adherence", "text": "Her çalışma oturumunun başında net bir hedef belirlerim."}, {"id": "con1", "dimension": "consistency", "text": "Sınav yakın olmasa da düzenli çalışırım."}, {"id": "con2", "dimension": "consistency", "text": "Çalışmamı son ana bırakmadan haftaya yayarım."}, {"id": "con3", "dimension": "consistency", "text": "Çalışma saatlerim büyük ölçüde düzenlidir."}, {"id": "con4", "dimension": "consistency", "text": "Yoğun haftalarda bile tekrar alışkanlığımı sürdürürüm."}, {"id": "err1", "dimension": "error_review", "text": "Deneme sonrası yanlış ve boşlarımı tek tek incelerim."}, {"id": "err2", "dimension": "error_review", "text": "Yanlışlarımı nedenine göre ayırırım (bilgi eksiği, dikkat, süre)."}, {"id": "err3", "dimension": "error_review", "text": "Sık yanlış yaptığım kazanımlar için ek çalışma planlarım."}, {"id": "err4", "dimension": "error_review", "text": "Yanlış defterimi ya da listemi düzenli tekrar ederim."}, {"id": "per1", "dimension": "persistence", "text": "Zorlandığım konularda vazgeçmeden farklı kaynaklara başvururum."}, {"id": "per2", "dimension": "persistence", "text": "Takıldığım noktaları çözüme kavuşana kadar takip ederim."}, {"id": "per3", "dimension": "persistence", "text": "Uzun ve zor görevleri parçalara bölüp tamamlarım."}, {"id": "per4", "dimension": "persistence", "text": "Beklediğim sonucu alamadığımda nedenini inceleyip devam ederim."}, {"id": "pac1", "dimension": "pace", "text": "Görevlerime ayırdığım süreyi önceden tahmin edebilirim."}, {"id": "pac2", "dimension": "pace", "text": "Denemelerde zamanı bölümlere göre planlarım."}, {"id": "pac3", "dimension": "pace", "text": "Sınavda zor soruları stratejik olarak sona bırakırım."}, {"id": "pac4", "dimension": "pace", "text": "Uzun çalışmalarda düzenli ve kısa molalar planlarım."}, {"id": "foc1", "dimension": "focus", "text": "Çalışırken bildirimleri ve dikkat dağıtıcıları kapatırım."}, {"id": "foc2", "dimension": "focus", "text": "Odaklanabileceğim bir çalışma ortamı hazırlarım."}, {"id": "foc3", "dimension": "focus", "text": "Derste önemli noktaları not alırım."}, {"id": "foc4", "dimension": "focus", "text": "Okuduğumu kendi cümlelerimle özetleyebilirim."}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',9,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_bilgi_v1','OGRENCI_BILGI_V1','Öğrenci Bilgi Formu','CUSTOM_EDUCATIONAL','2.0','Rehber öğretmenin öğrenciyi tanıması için kısa bilgi formu. Sağlık ve aile içi hassas ayrıntılar sorulmaz; bunlar gerekirse yüz yüze konuşulur.','{"items": [{"id": "b1", "type": "CHOICE", "text": "Okula nasıl geliyorsun?", "options": [{"id": "yurume", "text": "Yürüyerek"}, {"id": "servis", "text": "Servisle"}, {"id": "toplu", "text": "Toplu taşımayla"}, {"id": "aile", "text": "Ailemle"}]}, {"id": "b2", "type": "CHOICE", "text": "Evde ders çalışabileceğin sessiz bir yerin var mı?", "options": [{"id": "evet", "text": "Evet"}, {"id": "bazen", "text": "Bazen"}, {"id": "hayir", "text": "Hayır"}]}, {"id": "b3", "type": "TEXT", "text": "En sevdiğin ders hangisi ve neden?", "optional": true}, {"id": "b4", "type": "TEXT", "text": "Zorlandığın ders ya da konu hangisi?", "optional": true}, {"id": "b5", "type": "TEXT", "text": "Boş zamanlarında neler yapmaktan hoşlanırsın?", "optional": true}, {"id": "b6", "type": "TEXT", "text": "Gelecekte ne olmak istersin?", "optional": true}, {"id": "b7", "type": "YESNO", "text": "Okulda bir sorun yaşadığında konuşabileceğin bir yetişkin var mı?"}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',NULL,NULL,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_problem_v1','PROBLEM_TARAMA_V1','Problem Tarama Listesi','CUSTOM_EDUCATIONAL','2.0','Öğrencinin kendisi için önemli gördüğü konuları işaretlediği kısa liste. Puan tanı değildir; işaretlenen konular görüşme başlığı olarak kullanılır.','{"items": [{"id": "p1", "type": "YESNO", "dimension": "school", "text": "Derslerde başarılı olamamaktan endişe ediyorum.", "reverse": true}, {"id": "p2", "type": "YESNO", "dimension": "school", "text": "Derste anlatılanları anlamakta zorlanıyorum.", "reverse": true}, {"id": "p3", "type": "YESNO", "dimension": "school", "text": "Ödevlerimi yetiştiremiyorum.", "reverse": true}, {"id": "p4", "type": "YESNO", "dimension": "school", "text": "Sınavlarda bildiğim soruları da yapamıyorum.", "reverse": true}, {"id": "p5", "type": "YESNO", "dimension": "friends", "text": "Arkadaş edinmekte zorlanıyorum.", "reverse": true}, {"id": "p6", "type": "YESNO", "dimension": "friends", "text": "Okulda kendimi yalnız hissediyorum.", "reverse": true}, {"id": "p7", "type": "YESNO", "dimension": "friends", "text": "Bazı arkadaşlarım benimle alay ediyor ya da beni dışlıyor.", "reverse": true}, {"id": "p8", "type": "YESNO", "dimension": "friends", "text": "Arkadaşlarımla sık sık tartışıyorum.", "reverse": true}, {"id": "p9", "type": "YESNO", "dimension": "self", "text": "Sık sık canım sıkılıyor ya da üzgün hissediyorum.", "reverse": true}, {"id": "p10", "type": "YESNO", "dimension": "self", "text": "Kendime güvenmekte zorlanıyorum.", "reverse": true}, {"id": "p11", "type": "YESNO", "dimension": "self", "text": "Sinirlendiğimde kendimi kontrol etmekte zorlanıyorum.", "reverse": true}, {"id": "p12", "type": "YESNO", "dimension": "self", "text": "Uyumakta güçlük çekiyorum.", "reverse": true}, {"id": "p13", "type": "YESNO", "dimension": "future", "text": "Gelecekte ne yapmak istediğimi bilmiyorum.", "reverse": true}, {"id": "p14", "type": "YESNO", "dimension": "future", "text": "Hangi okul ya da bölüme gideceğime karar veremiyorum.", "reverse": true}, {"id": "p15", "type": "YESNO", "dimension": "future", "text": "Hedeflerime ulaşamayacağımı düşünüyorum.", "reverse": true}, {"id": "p16", "type": "YESNO", "dimension": "screen", "text": "Telefon, tablet ya da oyunda geçirdiğim süreyi azaltmakta zorlanıyorum.", "reverse": true}, {"id": "p17", "type": "YESNO", "dimension": "screen", "text": "Ekran yüzünden ders çalışmayı erteliyorum.", "reverse": true}, {"id": "pz", "type": "TEXT", "text": "Rehber öğretmeninle konuşmak istediğin başka bir konu var mı?", "optional": true}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',5,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_kaygi_v1','SINAV_KAYGI_V1','Sınav Heyecanı Öz Değerlendirmesi','CUSTOM_EDUCATIONAL','2.0','Sınav öncesi ve sırasındaki düşünce, beden ve dikkat tepkilerini eğitim amacıyla değerlendirir. Klinik bir ölçek değildir; yüksek puan görüşme gerekçesidir, tanı değildir.','{"scale": {"min": 1, "max": 5, "labels": ["Hiç", "Nadiren", "Bazen", "Çoğu zaman", "Her zaman"]}, "items": [{"id": "k1", "dimension": "worry", "text": "Sınavdan önceki günlerde sınavı çok düşünürüm.", "reverse": false}, {"id": "k2", "dimension": "worry", "text": "Sınavda başarısız olursam ne olacağı aklımdan çıkmaz.", "reverse": false}, {"id": "k3", "dimension": "body", "text": "Sınav sırasında kalbimin hızlı attığını hissederim.", "reverse": false}, {"id": "k4", "dimension": "body", "text": "Sınavdan önce midem bulanır ya da başım ağrır.", "reverse": false}, {"id": "k5", "dimension": "focus", "text": "Sınavda bildiğim şeyleri bir anda hatırlayamam.", "reverse": false}, {"id": "k6", "dimension": "focus", "text": "Sınav sırasında dikkatimi toplamakta zorlanırım.", "reverse": false}, {"id": "k7", "dimension": "coping", "text": "Sınavdan önce kendimi sakinleştirebilirim.", "reverse": true}, {"id": "k8", "dimension": "coping", "text": "Kötü geçen bir sınavdan sonra toparlanabilirim.", "reverse": true}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',5,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_ekran_v1','EKRAN_KULLANIM_V1','Ekran Kullanım Alışkanlıkları','CUSTOM_EDUCATIONAL','2.0','Ekran süresi, uyku öncesi kullanım ve kontrol duygusunu eğitim amacıyla değerlendirir. Bağımlılık tanısı koymaz; sonuçlar öğrenci ve aileyle konuşmak içindir.','{"items": [{"id": "e1", "type": "CHOICE", "dimension": "time", "text": "Okul günlerinde ders dışı ekran (telefon, tablet, oyun, TV) süren yaklaşık ne kadar?", "options": [{"id": "a", "text": "1 saatten az", "value": 100}, {"id": "b", "text": "1–2 saat", "value": 70}, {"id": "c", "text": "2–4 saat", "value": 35}, {"id": "d", "text": "4 saatten fazla", "value": 0}]}, {"id": "e2", "type": "CHOICE", "dimension": "sleep", "text": "Uyumadan önceki son bir saatte ekrana bakar mısın?", "options": [{"id": "a", "text": "Hiç", "value": 100}, {"id": "b", "text": "Bazen", "value": 50}, {"id": "c", "text": "Her gece", "value": 0}]}, {"id": "e3", "type": "YESNO", "dimension": "control", "text": "Ekran süremi azaltmak istediğimde azaltabilirim."}, {"id": "e4", "type": "YESNO", "dimension": "control", "text": "Ekran yüzünden ödevimi ya da ders çalışmamı ertelediğim olur.", "reverse": true}, {"id": "e5", "type": "YESNO", "dimension": "social", "text": "Ekran yüzünden ailemle tartıştığım olur.", "reverse": true}, {"id": "e6", "type": "YESNO", "dimension": "social", "text": "Ekran dışında keyif aldığım etkinlikler (spor, sanat, arkadaşlarla oyun) var."}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',4,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_basarisizlik_v1','BASARISIZLIK_NEDEN_V1','Başarıyı Etkileyen Nedenler','CUSTOM_EDUCATIONAL','2.0','Öğrencinin kendi gözünden akademik başarısını etkileyen nedenleri belirler. Sonuçlar haftalık program ve görüşme için kullanılır.','{"items": [{"id": "n1", "type": "YESNO", "dimension": "reasons", "text": "Konuları düzenli tekrar etmiyorum.", "reverse": true}, {"id": "n2", "type": "YESNO", "dimension": "reasons", "text": "Ders çalışmaya başlamakta zorlanıyorum.", "reverse": true}, {"id": "n3", "type": "YESNO", "dimension": "reasons", "text": "Derste anlatılanları kaçırıyorum.", "reverse": true}, {"id": "n4", "type": "YESNO", "dimension": "reasons", "text": "Soru çözme pratiğim az.", "reverse": true}, {"id": "n5", "type": "YESNO", "dimension": "reasons", "text": "Sınav sırasında heyecanlanıyorum.", "reverse": true}, {"id": "n6", "type": "YESNO", "dimension": "reasons", "text": "Sınavda süreyi iyi kullanamıyorum.", "reverse": true}, {"id": "n7", "type": "YESNO", "dimension": "reasons", "text": "Evde çalışma ortamım uygun değil.", "reverse": true}, {"id": "n8", "type": "YESNO", "dimension": "reasons", "text": "Uykumu alamıyorum.", "reverse": true}, {"id": "n9", "type": "YESNO", "dimension": "reasons", "text": "Hangi konuya çalışacağımı bilemiyorum.", "reverse": true}, {"id": "n10", "type": "YESNO", "dimension": "reasons", "text": "Ekran ve telefon dikkatimi dağıtıyor.", "reverse": true}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',5,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_ilgi_v1','ILGI_MESLEK_V1','İlgi ve Meslek Keşfi','CUSTOM_EDUCATIONAL','2.0','İki etkinlikten hangisini daha çok sevdiğini seçerek ilgi alanlarını keşfeder. Sonuç bir meslek önerisi değil, kariyer görüşmesine başlangıçtır.','{"areas": {"tech": "Sayısal ve teknik", "nature": "Doğa ve sağlık", "social": "İnsanlara yardım", "art": "Sanat ve tasarım", "lead": "İletişim ve girişim", "order": "Düzen ve ofis"}, "items": [{"id": "i1", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bir makinenin nasıl çalıştığını incelemek", "dimension": "tech"}, "b": {"text": "Bir afiş ya da resim tasarlamak", "dimension": "art"}}, {"id": "i2", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bitki ya da hayvanlarla ilgilenmek", "dimension": "nature"}, "b": {"text": "Bir sınıf etkinliği düzenleyip yönetmek", "dimension": "lead"}}, {"id": "i3", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bir arkadaşıma derslerinde yardım etmek", "dimension": "social"}, "b": {"text": "Dağınık bir listeyi düzenleyip sınıflandırmak", "dimension": "order"}}, {"id": "i4", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bilgisayarda basit bir program yazmak", "dimension": "tech"}, "b": {"text": "Küçük çocuklara bir şey öğretmek", "dimension": "social"}}, {"id": "i5", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bir deney yapıp sonucunu gözlemlemek", "dimension": "nature"}, "b": {"text": "Bir bütçe ya da hesap tablosu tutmak", "dimension": "order"}}, {"id": "i6", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Müzik ya da tiyatro ile uğraşmak", "dimension": "art"}, "b": {"text": "Bir fikri sınıfa sunup ikna etmek", "dimension": "lead"}}, {"id": "i7", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Robot ya da maket yapmak", "dimension": "tech"}, "b": {"text": "İnsan vücudunun nasıl çalıştığını öğrenmek", "dimension": "nature"}}, {"id": "i8", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bir yardım kampanyasında görev almak", "dimension": "social"}, "b": {"text": "Bir hikâye ya da şiir yazmak", "dimension": "art"}}, {"id": "i9", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Okul kütüphanesinin kayıtlarını tutmak", "dimension": "order"}, "b": {"text": "Okul gazetesinin sorumlusu olmak", "dimension": "lead"}}, {"id": "i10", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Bir sorunu matematikle çözmek", "dimension": "tech"}, "b": {"text": "Belgeleri düzenli bir şekilde arşivlemek", "dimension": "order"}}, {"id": "i11", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Çevre temizliği projesinde çalışmak", "dimension": "nature"}, "b": {"text": "Bir arkadaşımın sorununu dinlemek", "dimension": "social"}}, {"id": "i12", "type": "AB", "text": "Hangisini yapmayı daha çok istersin?", "a": {"text": "Fotoğraf ya da video çekip düzenlemek", "dimension": "art"}, "b": {"text": "Bir elektrik devresi kurmak", "dimension": "tech"}}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',7,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_assessment_instruments(id,code,title,category,version,description,question_schema_json,evidence_level,active,review_status,grade_min,grade_max,delivery_modes_json) VALUES('gi_sosyometri_v1','SOSYOMETRI_V1','Sınıf İlişkileri (Sosyometri)','CUSTOM_EDUCATIONAL','2.0','Sınıf içindeki arkadaşlık ve iş birliği ilişkilerini görmek için yalnız olumlu seçimler sorulur. Sonuçları yalnız rehber öğretmen görür; öğrencilere ya da velilere gösterilmez.','{"items": [{"id": "s1", "type": "PEER", "max": 3, "text": "Bir grup çalışmasında kimlerle çalışmak istersin? (en fazla 3 kişi)"}, {"id": "s2", "type": "PEER", "max": 3, "text": "Teneffüste kimlerle vakit geçirmekten hoşlanırsın? (en fazla 3 kişi)"}, {"id": "s3", "type": "PEER", "max": 2, "text": "Bir sorunun olduğunda sınıfta kime anlatırsın? (en fazla 2 kişi)", "optional": true}]}','INTERNAL_EDUCATIONAL',0,'REVIEW',4,12,'["ONLINE"]');
INSERT OR IGNORE INTO guidance_survey_templates(id,code,kind,title,description,forms_json) VALUES('gst_riba','RIBA','RIBA','Rehberlik İhtiyacı Belirleme Anketi (RİBA)','MEB RİBA uygulaması için isimsiz anket altyapısı. Formların maddeleri resmî MEB kaynağından kullanım teyidi alındıktan sonra Süper Admin tarafından yüklenir.','{"answerLabels": {"A": "A", "B": "B"}, "forms": [{"code": "OGRENCI_ILKOKUL", "title": "Öğrenci formu (3–4. sınıf)", "audience": "STUDENT", "gradeMin": 3, "gradeMax": 4, "items": []}, {"code": "OGRENCI_ORTAOKUL", "title": "Öğrenci formu (ortaokul)", "audience": "STUDENT", "gradeMin": 5, "gradeMax": 8, "items": []}, {"code": "OGRENCI_LISE", "title": "Öğrenci formu (lise)", "audience": "STUDENT", "gradeMin": 9, "gradeMax": 12, "items": []}, {"code": "VELI", "title": "Veli formu", "audience": "PARENT", "items": []}, {"code": "OGRETMEN", "title": "Öğretmen formu", "audience": "TEACHER", "items": []}]}');
INSERT OR IGNORE INTO guidance_survey_templates(id,code,kind,title,description,forms_json) VALUES('gst_climate','OKUL_IKLIMI','CLIMATE','Okul İklimi ve Akran İlişkileri Anketi','Okulda güvenlik, aidiyet, akran ilişkileri ve akran zorbalığını isimsiz olarak ölçer. Önleyici çalışmaları planlamak içindir.','{"scale": {"min": 1, "max": 5, "labels": ["Hiç katılmıyorum", "Katılmıyorum", "Kararsızım", "Katılıyorum", "Tamamen katılıyorum"]}, "forms": [{"code": "OGRENCI", "title": "Öğrenci formu (5–12. sınıf)", "audience": "STUDENT", "gradeMin": 5, "gradeMax": 12, "items": [{"id": "c1", "type": "LIKERT", "dimension": "safe", "text": "Okulda kendimi güvende hissederim.", "reverse": false}, {"id": "c2", "type": "LIKERT", "dimension": "safe", "text": "Teneffüslerde ve koridorlarda kendimi güvende hissederim.", "reverse": false}, {"id": "c3", "type": "LIKERT", "dimension": "belong", "text": "Okulumda kendimi bir parçası gibi hissederim.", "reverse": false}, {"id": "c4", "type": "LIKERT", "dimension": "belong", "text": "Sınıfımda bana değer verildiğini hissederim.", "reverse": false}, {"id": "c5", "type": "LIKERT", "dimension": "peer", "text": "Sınıfımda kimseyle alay edilmez ya da kimse dışlanmaz.", "reverse": false}, {"id": "c6", "type": "LIKERT", "dimension": "peer", "text": "Bir arkadaşıma zorbalık yapıldığını görürsem bir yetişkine söylerim.", "reverse": false}, {"id": "c7", "type": "LIKERT", "dimension": "peer", "text": "Son bir ayda okulda bana lakap takıldığı, itildiğim ya da dışlandığım oldu.", "reverse": true}, {"id": "c8", "type": "LIKERT", "dimension": "peer", "text": "Son bir ayda internette ya da telefonda bana kötü mesaj gönderildiği oldu.", "reverse": true}, {"id": "c9", "type": "LIKERT", "dimension": "adult", "text": "Bir sorun yaşadığımda okulda konuşabileceğim bir yetişkin var.", "reverse": false}, {"id": "c10", "type": "LIKERT", "dimension": "adult", "text": "Öğretmenlerim zorbalık olduğunda bir şeyler yapar.", "reverse": false}]}]}');
